do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero) values ($q$UBER$q$,$q$Uber Technologies$q$,$q$consumer$q$,$q$large$q$,true,true),($q$AAPL$q$,$q$Apple$q$,$q$consumer$q$,$q$large$q$,true,false),($q$META$q$,$q$Meta Platforms$q$,$q$consumer$q$,$q$large$q$,true,false),($q$MSFT$q$,$q$Microsoft$q$,$q$business$q$,$q$large$q$,true,false),($q$PLTR$q$,$q$Palantir Technologies$q$,$q$business$q$,$q$large$q$,true,false),($q$NVDA$q$,$q$NVIDIA$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$TSM$q$,$q$Taiwan Semiconductor Manufacturing$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$AMD$q$,$q$Advanced Micro Devices$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$DASH$q$,$q$DoorDash$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$NET$q$,$q$Cloudflare$q$,$q$business$q$,$q$mid$q$,true,false),($q$CRWV$q$,$q$CoreWeave$q$,$q$infrastructure$q$,$q$mid$q$,true,true),($q$CBRS$q$,$q$Cerebras Systems$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$NBIS$q$,$q$Nebius Group$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$LYFT$q$,$q$Lyft$q$,$q$consumer$q$,$q$small$q$,true,true),($q$APLD$q$,$q$Applied Digital$q$,$q$infrastructure$q$,$q$small$q$,true,false),($q$AMZN$q$,$q$Amazon$q$,$q$consumer$q$,$q$large$q$,true,false),($q$GOOGL$q$,$q$Alphabet$q$,$q$consumer$q$,$q$large$q$,true,false),($q$TSLA$q$,$q$Tesla$q$,$q$consumer$q$,$q$large$q$,true,false),($q$ORCL$q$,$q$Oracle$q$,$q$business$q$,$q$large$q$,true,false),($q$INTC$q$,$q$Intel$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$LCID$q$,$q$Lucid$q$,$q$consumer$q$,$q$small$q$,true,false),($q$LIME$q$,$q$Lime$q$,$q$consumer$q$,$q$small$q$,true,false),($q$CART$q$,$q$Instacart$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$GRAB$q$,$q$Grab$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$AUR$q$,$q$Aurora$q$,$q$business$q$,$q$small$q$,true,false) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero;
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$AUMOVIO$q$,$q$public_company$q$),($q$DENSO$q$,$q$public_company$q$),($q$Hirschbach$q$,$q$private_company$q$),($q$PACCAR$q$,$q$public_company$q$),($q$Ryder Systems$q$,$q$public_company$q$),($q$Toyota$q$,$q$public_company$q$),($q$Uber Freight$q$,$q$private_company$q$),($q$Volvo$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$Amended and Restated Strategic Partnership Agreement, dated September 27, 2023, by and among the Registrant and Aurora Operations, Inc., and Continental Automotive Technologies GmbH and Continental Autonomous Mobility Germany GmbH$q$),(2,$q$Further, we continued our strategic collaboration with Ryder Systems, piloting on-site fleet maintenance to support current autonomous freight pilot operations and prepare for commercial operation at scale.$q$),(3,$q$In April 2023, we entered into an exclusive partnership with Continental, now AUMOVIO, to deliver the first commercially scalable future generation of the Aurora Driver.$q$),(4,$q$In April 2025, we launched driverless commercial operations with Hirschbach and Uber Freight and have since expanded our driverless customer cohort.$q$),(5,$q$In February 2021, we announced a long-term, global, and strategic collaboration with Toyota and DENSO, one of the largest global automotive manufacturers and tier-one automotive suppliers, respectively, to build and globally deploy self-driving cars at scale.$q$),(6,$q$In January 2021, we entered into a global strategic partnership with PACCAR.$q$),(7,$q$In March 2021, Volvo selected us as its technology provider to develop and jointly commercialize Level 4 Class 8 trucks in North America.$q$),(8,$q$In addition to acquiring Uber’s self-driving unit, we announced a strategic partnership with Uber that connects our technology to the world’s leading ride-hailing platform and strengthens our position to deliver the Aurora Driver broadly.$q$),(9,$q$In support of our partnership with Uber, and concurrent with the acquisition of Uber’s self-driving unit, Uber invested $400 million in Aurora.$q$),(10,$q$Interruption or failure of Amazon Web Services or other information technology and communications systems that we rely upon could materially and adversely affect our business, financial condition and results of operations.$q$),(11,$q$On April 26, 2023, we entered into the Strategic Partnership Agreement with Continental, now AUMOVIO, which was amended and restated on September 27, 2023.$q$),(12,$q$Several companies, including, but not limited to, Waymo, Tesla, Zoox/Amazon, Motional, Torc Robotics, Kodiak Robotics, PlusAI, Waabi, Stack AV and Mobileye are investing heavily in building this technology.$q$),(13,$q$We currently rely on Amazon Web Services (“AWS”) to host our technology and support our technology development.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$partners$q$,$q$AUR$q$,$q$PACCAR$q$,$q${6}$q$::int[],$q${business}$q$::text[],null,null,null,null),(2,$q$partners$q$,$q$AUR$q$,$q$Volvo$q$,$q${7}$q$::int[],$q${business}$q$::text[],null,null,null,null),(3,$q$partners$q$,$q$AUR$q$,$q$Toyota$q$,$q${5}$q$::int[],$q${business}$q$::text[],null,null,null,null),(4,$q$partners$q$,$q$AUR$q$,$q$DENSO$q$,$q${5}$q$::int[],$q${business}$q$::text[],null,null,null,null),(5,$q$partners$q$,$q$AUR$q$,$q$Uber$q$,$q${8}$q$::int[],$q${business}$q$::text[],null,null,null,null),(6,$q$invests$q$,$q$Uber$q$,$q$AUR$q$,$q${9}$q$::int[],$q${business}$q$::text[],null,null,null,null),(7,$q$partners$q$,$q$AUR$q$,$q$AUMOVIO$q$,$q${3,11,1}$q$::int[],$q${business,risk_factors,notes}$q$::text[],null,null,null,null),(8,$q$partners$q$,$q$AUR$q$,$q$Ryder Systems$q$,$q${2}$q$::int[],$q${business}$q$::text[],null,null,null,null),(9,$q$sells_to$q$,$q$AUR$q$,$q$Hirschbach$q$,$q${4}$q$::int[],$q${business}$q$::text[],null,null,null,null),(10,$q$sells_to$q$,$q$AUR$q$,$q$Uber Freight$q$,$q${4}$q$::int[],$q${business}$q$::text[],null,null,null,null),(11,$q$competes$q$,$q$AUR$q$,$q$Waymo$q$,$q${12}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(12,$q$supplies$q$,$q$Amazon$q$,$q$AUR$q$,$q${10,13}$q$::int[],$q${risk_factors,risk_factors}$q$::text[],null,null,null,null);
create function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Uber$q$ then ticker=$q$UBER$q$ when $q$Waymo$q$ then ticker=$q$GOOGL$q$ when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Lyft$q$ then ticker=$q$LYFT$q$ when $q$AUR$q$ then ticker=$q$AUR$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$AUR FY2025 10-K (M6)$q$,'claude-sonnet-5-5 via Claude Code session',0,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1828108/000182810826000016/aur-20251231.htm$q$,r.sec[k],t,true,$q$2026-02-11$q$ from _q where i=r.qs[k]; end loop; end loop;
end $do$;
